    if (p.x() < q.x()) return CGAL::SMALLER;
    if (p.x() > q.x()) return CGAL::LARGER;
    return CGAL::EQUAL;
}

int main() {
    Point_2 p1(1.0, 2.0);
    Point_2 p2(3.0, 4.0);
